#!/bin/bash
# Generated by Claude Fable 5 (Anthropic)
# FISH overhead experiment: two sequential fresh-container logging_simulator runs
# on the SAME image (fishwait7), identical config, identical measurement probes:
#   run 1 "traced"   — full FISH (LTTng per_instance + CUDA event trace + nsys),
#                      same as run_logging_sim_bag_prov.sh (r29 config, bag -r 0.5)
#   run 2 "baseline" — FISH completely off (no wrapper, no LTTng, no daemon);
#                      the script itself mirrors FISH's orchestration: wait for
#                      the node graph to stabilise, then ros2 bag play -r 0.5.
# Probes (identical in BOTH runs, stock ros2, started before launch):
#   - cpu.log   : sum of utime+stime jiffies over all /proc/<pid>/stat in the
#                 container PID namespace, every 2 s  → container CPU seconds
#   - diag.log  : ros2 topic echo /diagnostics — Autoware's own measurements
#                 (topic_state_monitor measured_rate, processing_time_ms,
#                 pipeline_latency_monitor Total Latency)
# Probe overhead is equal on both sides and cancels in the comparison.
#
# Outputs: $HOME/fish_traces/overhead_<STAMP>/{traced,baseline}/ + the traced
# run's normal fish_<ts> session dir (for discarded-event / event-count stats).
set -e
DEST=$HOME/fish_traces
IMG=${IMG:-autoware-dev-trt-a1000-fishwait7:latest}
FISH_SRC=/home/tue037807/fish_interfere
STAMP=$(date +%Y%m%d_%H%M%S)
OUTROOT=$DEST/overhead_$STAMP
mkdir -p "$OUTROOT"
docker image inspect $IMG >/dev/null 2>&1 || { echo "[ovh] $IMG not built"; exit 2; }

# ---- probe block, runs inside the container -----------------------------------
# $1 = output dir (inside container). Uses ONLY stock ROS (no FISH wrapper).
read -r -d '' PROBE_FN <<'EOF' || true
probe_start() {
    POUT=$1; mkdir -p "$POUT"
    # NOTE: subshell must drop the caller's `set -e` — a /proc/<pid>/stat that
    # vanishes between glob and open makes awk exit non-zero, which must not
    # kill the sampler (it did, first version: 1 sample in the boot storm).
    ( set +e
      while :; do
        printf "%s " "$(date +%s.%N)"
        awk '{ i=index($0,")"); n=split(substr($0,i+2),a," "); s+=a[12]+a[13]; c++ }
             END{ printf "%d %d\n", s, c }' /proc/[0-9]*/stat 2>/dev/null || echo "NA NA"
        sleep 2
      done > "$POUT/cpu.log" 2>/dev/null ) &
    echo $! > /tmp/probe_cpu_pid
    # Rates and processing times come from Autoware's OWN measurements inside
    # /diagnostics (topic_state_monitor measured_rate, processing_time_ms,
    # pipeline_latency_monitor Total Latency) — no hz probes: the only external
    # touch is this one low-frequency /diagnostics subscription. (hz probes
    # were dropped after the 2026-08-30 pilot; per-topic hz ↔ measured_rate
    # cross-check lives in overhead_20260830_*/ of that pilot.)
    setsid bash -c "while :; do /opt/ros/humble/bin/ros2 topic echo /diagnostics >> '$POUT/diag.log' 2>&1; sleep 5; done" &
    echo $! > /tmp/probe_diag_pid
    echo "[probe] started → $POUT"
}
probe_stop() {
    for p in $(cat /tmp/probe_cpu_pid /tmp/probe_diag_pid 2>/dev/null); do
        kill -- -"$p" 2>/dev/null || kill "$p" 2>/dev/null
    done
    echo "[probe] stopped"
}
EOF

run_one() {  # $1 = traced|baseline
    MODE=$1
    NAME=autoware-fishwait7-overhead-$MODE
    docker rm -f $NAME 2>/dev/null || true
    echo "=================================================================="
    echo "[ovh] $MODE run starting ($(date +%T))"
    local FISH_ENV=()
    [ "$MODE" = traced ] && FISH_ENV=(-e FISH_ENABLED=1 -e FISH_CUDA_EVENT_TRACE=1 -e FISH_NSYS_DRAIN=15)
    docker run -d --gpus all --privileged --net host --shm-size=2g \
        --name $NAME \
        -v "$DEST:/root/fish_traces" \
        -v "$HOME/fish_provenance_ros:/opt/fish_provenance_ros:ro" \
        "${FISH_ENV[@]}" \
        $IMG bash -c 'sleep 3600' >/dev/null
    docker exec $NAME mkdir -p /root/fish_traces/overhead_$STAMP/$MODE

    if [ "$MODE" = traced ]; then
        docker exec $NAME rm -rf /root/fish_interfere
        docker cp "$FISH_SRC" $NAME:/root/fish_interfere
    fi

    timeout 900 docker exec \
        -e MODE=$MODE -e STAMP=$STAMP -e PROBE_FN="$PROBE_FN" \
        $NAME bash -c '
        set -e
        export PYTHONUNBUFFERED=1
        eval "$PROBE_FN"
        POUT=/root/fish_traces/overhead_$STAMP/$MODE
        source /opt/ros/humble/setup.bash
        source /opt/autoware/setup.bash
        env | grep -E "RMW|CYCLONE|FISH" > "$POUT/env.txt" || true
        nproc >> "$POUT/env.txt"

        if [ "$MODE" = traced ]; then
            source /root/trace_overlay_ws/install/setup.bash
            cd /root/fish_interfere
            FISH_SETUP_PARENT=1 source scripts/install_fish.sh 2>&1 | tail -3
            export PATH=/opt/ros/humble/fish/bin:$PATH
            export PYTHONPATH=/opt/ros/humble/fish/python:$PYTHONPATH
            export FISH_ENABLED=1
            unset RMW_IMPLEMENTATION CYCLONEDDS_URI
            INI=/opt/ros/humble/fish/fish_settings.ini
            sed -i "s|^rmw_implementation *=.*|rmw_implementation = rmw_cyclonedds_cpp|" $INI
            sed -i "s|^cyclonedds_uri *=.*|cyclonedds_uri = |" $INI
            sed -i "s|^per_instance *=.*|per_instance = true|" $INI
            sed -i "s|ros2 bag play ~/autoware_map/sample-rosbag -r 0.2|ros2 bag play ~/autoware_map/sample-rosbag -r 0.5|" $INI || true
        else
            export RMW_IMPLEMENTATION=rmw_cyclonedds_cpp
            unset CYCLONEDDS_URI
        fi

        # probes BEFORE launch, identical both sides (stock ros2, needs RMW set)
        RMW_IMPLEMENTATION=rmw_cyclonedds_cpp probe_start "$POUT"
        date +%s.%N > "$POUT/t_launch.txt"

        set +e
        if [ "$MODE" = traced ]; then
            # FISH daemon handles: stable-wait → bag play (-r 0.5) → auto-stop
            timeout 420 ros2 launch autoware_launch logging_simulator.launch.xml \
                map_path:=/root/autoware_map/sample-map-rosbag \
                vehicle_model:=sample_vehicle sensor_model:=sample_sensor_kit rviz:=false \
                > "$POUT/launch.log" 2>&1
            echo "[ovh] launch rc=$? (timeout=natural end)"
            sleep 25
        else
            timeout 420 ros2 launch autoware_launch logging_simulator.launch.xml \
                map_path:=/root/autoware_map/sample-map-rosbag \
                vehicle_model:=sample_vehicle sensor_model:=sample_sensor_kit rviz:=false \
                > "$POUT/launch.log" 2>&1 &
            LPID=$!
            # mirror FISH stable-wait: node count unchanged for 5 polls x 3 s
            PREV=-1; STABLE=0
            for i in $(seq 1 80); do
                N=$(/opt/ros/humble/bin/ros2 node list 2>/dev/null | wc -l)
                if [ "$N" = "$PREV" ] && [ "$N" -gt 50 ]; then STABLE=$((STABLE+1)); else STABLE=0; fi
                PREV=$N
                [ $STABLE -ge 5 ] && break
                sleep 3
            done
            echo "[ovh] stable at $N nodes (poll $i)"; echo "$N $i" > "$POUT/stable.txt"
            date +%s.%N > "$POUT/t_replay.txt"
            ros2 bag play ~/autoware_map/sample-rosbag -r 0.5 -s sqlite3 \
                > "$POUT/replay.log" 2>&1
            echo "[ovh] replay done rc=$?"
            date +%s.%N > "$POUT/t_replay_end.txt"
            sleep 20
            kill -INT $LPID 2>/dev/null; sleep 15
        fi
        probe_stop
        [ "$MODE" = traced ] && ls -td /root/fish_traces/fish_2026* 2>/dev/null | head -1 > "$POUT/session.txt"
        echo "[ovh] $MODE done"
    '
    echo "[ovh] $MODE exec rc=$?"
    docker rm -f $NAME >/dev/null 2>&1 || true
}

run_one traced
run_one baseline
echo "[ovh] both runs complete → $OUTROOT"
ls -la "$OUTROOT"/traced "$OUTROOT"/baseline
